<template>
  <v-container fill-height class="pos-blocked">
    <v-row class="text-center">
      <v-col cols="12" class="pt-0">
        <v-row align="center" justify="center">
          <v-col align="center" justify="center" class="pt-0">
            <Header />
          </v-col>
        </v-row>
      </v-col>
      <v-col cols="12" class="py-0">
        <v-row align="center" justify="center">
          <v-col>
            <PosBlockedBody :reason="reason" />
          </v-col>
        </v-row>
      </v-col>
      <v-col cols="12" class="py-0">
        <v-row align="center" justify="center">
          <v-col align="center" class="py-0">
            <Footer />
          </v-col>
        </v-row>
      </v-col>
    </v-row>
  </v-container>
</template>

<script>
import Header from '@/components/AuthViews/Header'
import PosBlockedBody from '@/components/PosBlockedView/PosBlockedBody'
import Footer from '@/components/AuthViews/Footer'

export default {
  name: 'PosBlockedView',
  components: {
    Header,
    PosBlockedBody,
    Footer,
  },
  data() {
    return {
      reason: '',
    }
  },
  mounted() {
    if (this.$route.query && this.$route.query.reason)
      this.reason = this.$route.query.reason
    this.$track({
      type: 'system',
      action: 'Block',
      category: 'Blocked',
      screen: 'PosBlockedView',
      name: `Pos blocked: ${this.reason || 'unknown'}`,
    })
  },
}
</script>

<style>
.pos-blocked {
  width: 900px;
}
</style>
