<template>
  <v-card class="pa-6 form-card">
    <div class="primary form-top-bar" />
    <v-card-title class="justify-center">
      <FormattedText
        type="text-h5"
        className="font-weight-bold"
        color="textPrimary"
        intl
        value="posBlockedView.title"
      />
    </v-card-title>

    <v-list-item-avatar size="100" class="mb-0">
      <v-icon size="90">mdi-lock-alert</v-icon>
    </v-list-item-avatar>
    <v-card-text class="text--primary">
      <FormattedText
        type="text-h6"
        color="textPrimary"
        intl
        :value="errorMessage"
      />
      <FormattedText
        class="pt-6"
        type="text-h6"
        className="font-weight-bold"
        color="textPrimary"
        intl
        value="posBlockedView.firstStep"
      />
      <FormattedText
        type="text-h6"
        className="font-weight-bold"
        color="textPrimary"
        intl
        value="posBlockedView.secondStep"
      />
      <FormattedText
        type="text-h6"
        className="font-weight-bold"
        color="textPrimary"
        intl
        value="posBlockedView.thirdStep"
      />
      <FormattedText
        class="pt-6"
        type="text-h6"
        color="textPrimary"
        intl
        value="posBlockedView.contactUs"
      />
      <FormattedText
        type="text-h5"
        class="pt-4"
        className="font-weight-bold"
        color="textPrimary"
        value="ayuda@frogtek.org"
      />
    </v-card-text>

    <v-card-actions>
      <Button
        className="submit-button"
        block
        large
        rounded
        @click="closeTT"
        intl
        text="posBlockedView.closeTT"
        textType="text-subtitle-2"
        textClass="text-capitalize"
        v-track:click="{
          category: 'Block',
          screen: 'PosBlockedBody',
          name: 'Close Tiendatek',
        }"
      />
    </v-card-actions>
  </v-card>
</template>

<script>
import rendererEventsService from '@/services/renderer/rendererEvents'

import FormattedText from '@/components/shared/FormattedText'
import Button from '@/components/shared/CustomButton'

export default {
  name: 'PosBlockedBody',
  components: { FormattedText, Button },
  props: {
    reason: {
      type: String,
      required: true,
    },
  },
  computed: {
    errorMessage() {
      switch (this.reason) {
        case 'no-license':
          return 'posBlockedView.generalBlock'
        case 'no-internet':
          return 'posBlockedView.noInternetBlock'
        case 'wrong-date':
          return 'posBlockedView.wrongDateBlock'
        default:
          return 'posBlockedView.generalBlock'
      }
    },
  },
  methods: {
    closeTT() {
      rendererEventsService.send('close-app')
    },
  },
}
</script>

<style lang="scss" scoped>
.form-card {
  border-radius: 8px !important;
  position: relative;
}
.form-top-bar {
  height: 8px;
  width: 100%;
  position: absolute;
  top: 0;
  left: 0;
}
.submit-button {
  min-width: 100% !important;
}
</style>
